*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --color-bg:          #f8f7f5;
  --color-surface:     #ffffff;
  --color-border:      #e2e0db;
  --color-accent:      #6246ea;
  --color-accent-dark: #4c35c4;
  --color-text:        #1a1a2e;
  --color-muted:       #6b6b80;
  --color-answer-bg:   #faf9ff;
  --radius:            12px;
  --shadow-sm:         0 1px 3px rgba(0,0,0,.08), 0 1px 2px rgba(0,0,0,.04);
  --shadow-md:         0 4px 12px rgba(0,0,0,.1);
  --transition:        220ms ease;
  font-size: 16px;
}

body {
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  background: var(--color-bg);
  color: var(--color-text);
  line-height: 1.6;
  min-height: 100vh;
}

/* ── Skip link ────────────────────────────────────────────────── */
.skip-link {
  position: absolute;
  top: -999px;
  left: 1rem;
  background: var(--color-accent);
  color: #fff;
  padding: .5rem 1rem;
  border-radius: var(--radius);
  font-weight: 600;
  text-decoration: none;
  z-index: 9999;
}
.skip-link:focus {
  top: 1rem;
}

/* ── Page layout ──────────────────────────────────────────────── */
.page-header {
  background: var(--color-surface);
  border-bottom: 1px solid var(--color-border);
  padding: 2.5rem 1.5rem;
  text-align: center;
}

.page-header__eyebrow {
  display: inline-block;
  font-size: .75rem;
  font-weight: 700;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: var(--color-accent);
  margin-bottom: .75rem;
}

.page-header h1 {
  font-size: clamp(1.75rem, 5vw, 2.75rem);
  font-weight: 800;
  letter-spacing: -.02em;
  line-height: 1.2;
  color: var(--color-text);
}

.page-header__subtitle {
  margin-top: .75rem;
  font-size: 1.05rem;
  color: var(--color-muted);
  max-width: 40ch;
  margin-inline: auto;
}

main {
  max-width: 720px;
  margin-inline: auto;
  padding: 3rem 1.5rem 4rem;
}

/* ── Section heading ──────────────────────────────────────────── */
.faq-section + .faq-section { margin-top: 3rem; }

.faq-section__label {
  font-size: .7rem;
  font-weight: 700;
  letter-spacing: .12em;
  text-transform: uppercase;
  color: var(--color-muted);
  margin-bottom: 1rem;
  padding-bottom: .5rem;
  border-bottom: 2px solid var(--color-border);
}

/* ── FAQ list ─────────────────────────────────────────────────── */
.faq-list {
  display: flex;
  flex-direction: column;
  gap: .75rem;
  list-style: none;
}

/* ── Individual item ──────────────────────────────────────────── */
.example {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius);
  box-shadow: var(--shadow-sm);
  overflow: hidden;
  transition: box-shadow var(--transition), border-color var(--transition);
}

.example:has([aria-expanded="true"]) {
  border-color: #c4bbf5;
  box-shadow: var(--shadow-md);
}

/* ── Question trigger ─────────────────────────────────────────── */
.example h3 {
  /* reset heading margin/padding; keep semantic heading */
  margin: 0;
}

.example h3 button {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  width: 100%;
  background: transparent;
  border: none;
  cursor: pointer;
  padding: 1.1rem 1.25rem;
  font-size: 1rem;
  font-weight: 600;
  color: var(--color-text);
  text-align: left;
  transition: background var(--transition), color var(--transition);
  border-radius: var(--radius);
}

.example h3 button:hover {
  background: #f4f2ff;
  color: var(--color-accent-dark);
}

.example h3 button:focus-visible {
  outline: 3px solid var(--color-accent);
  outline-offset: -3px;
  border-radius: var(--radius);
}

/* ── Chevron icon ─────────────────────────────────────────────── */
.faq-icon {
  flex-shrink: 0;
  width: 1.25rem;
  height: 1.25rem;
  color: var(--color-accent);
  transition: transform var(--transition);
}

.example h3 button[aria-expanded="true"] .faq-icon {
  transform: rotate(180deg);
}

/* ── Answer panel ─────────────────────────────────────────────── */
.details {
  padding: 0 1.25rem 1.25rem;
  background: var(--color-answer-bg);
  border-top: 1px solid var(--color-border);
}

.details p {
  padding-top: 1rem;
  font-size: .9625rem;
  color: var(--color-muted);
  line-height: 1.75;
}

.details p + p { margin-top: .75rem; }

/* ── Footer ───────────────────────────────────────────────────── */
.page-footer {
  text-align: center;
  padding: 2rem 1.5rem;
  font-size: .875rem;
  color: var(--color-muted);
  border-top: 1px solid var(--color-border);
}

/* ── Reduced motion ───────────────────────────────────────────── */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { transition: none !important; }
}

/* ── Forced colors ────────────────────────────────────────────── */
@media (forced-colors: active) {
  .example { border: 1px solid ButtonText; }
  .example h3 button { forced-color-adjust: auto; }
  .faq-icon { forced-color-adjust: auto; }
}

/* ── Reflow: 320 px ───────────────────────────────────────────── */
@media (max-width: 360px) {
  .example h3 button { padding: .9rem 1rem; font-size: .9375rem; }
  .details { padding: 0 1rem 1rem; }
}
