const { chromium } = require('/workspace/sandbox/skills/building-accessible-ui/disclosure-widget--framework-vanilla-js--style-modern/claude-sonnet-4.6__s1/node_modules/playwright');
const fs = require('fs');
const path = require('path');

const dir = '/workspace/sandbox/skills/building-accessible-ui/disclosure-widget--framework-vanilla-js--style-modern/claude-sonnet-4.6__s1';

(async () => {
  const html = fs.readFileSync(path.join(dir, 'index.html'), 'utf8');
  const css  = fs.readFileSync(path.join(dir, 'styles.css'), 'utf8');
  const js   = fs.readFileSync(path.join(dir, 'script.js'), 'utf8');

  // Inline CSS and JS so Playwright can render without a server
  const inlined = html
    .replace('<link rel="stylesheet" href="styles.css" />', `<style>${css}</style>`)
    .replace('<script src="script.js"></script>', `<script>${js}</script>`);

  const b = await chromium.launch();
  const page = await b.newPage();
  await page.setContent(inlined, { waitUntil: 'load' });
  await page.addScriptTag({ path: '/tmp/axe.min.js' });
  const r = await page.evaluate(async () => await window.axe.run());

  // Also test with one panel open
  await page.click('.faq-trigger');
  await page.addScriptTag({ path: '/tmp/axe.min.js' });
  const r2 = await page.evaluate(async () => await window.axe.run());
  await b.close();

  const merge = (res) => res.violations;
  const allViolations = [...merge(r), ...merge(r2)];
  const seen = new Set();
  const unique = allViolations.filter(v => { if (seen.has(v.id)) return false; seen.add(v.id); return true; });

  const wcag = unique.filter(v => !v.tags.includes('best-practice'));
  const bp   = unique.filter(v =>  v.tags.includes('best-practice'));

  const summarise = v => ({ id: v.id, impact: v.impact, targets: v.nodes.map(n => n.target), html: v.nodes.map(n => n.html) });
  console.log(JSON.stringify({ wcag: wcag.map(summarise), bp: bp.map(summarise) }, null, 2));
  process.exit(wcag.length ? 1 : 0);
})();
EOF
